import { buildMcq, buildNumerical } from './expandedHelpers.ts';
import type { CandidateQuestionInput } from './validationEngine.ts';

interface ChemSpec {
  topic: string;
  d: 'Easy' | 'Medium' | 'Hard';
  kind: 'MCQ' | 'Numerical' | 'MultiConcept';
  stem: string;
  ans: string;
  opts?: [string, string, string];
  sol: string;
  f: string;
}

function materializeChem(
  units: Array<{ code: string; chapter: string; items: ChemSpec[] }>
): CandidateQuestionInput[] {
  const out: CandidateQuestionInput[] = [];
  for (const unit of units) {
    unit.items.forEach((s, idx) => {
      const id = `CHM-EXP-${unit.code}-${String(idx + 1).padStart(2, '0')}`;
      const timeSec = s.d === 'Easy' ? 45 : s.d === 'Medium' ? 70 : 100;
      if (s.kind === 'Numerical') {
        out.push(
          buildNumerical({
            externalId: id,
            subject: 'Chemistry',
            chapter: unit.chapter,
            topic: s.topic,
            difficulty: s.d,
            questionText: s.stem,
            correctValue: s.ans,
            solution: s.sol,
            conceptTested: s.topic,
            formulaUsed: s.f,
            estimatedTimeSeconds: timeSec,
          })
        );
      } else {
        out.push(
          buildMcq({
            externalId: id,
            subject: 'Chemistry',
            chapter: unit.chapter,
            topic: s.topic,
            difficulty: s.d,
            questionType: s.kind === 'MultiConcept' ? 'MultiConcept' : 'MCQ',
            questionText: s.stem,
            correctOption: s.ans,
            correctExplanation: s.sol,
            distractors: (s.opts ?? []).map((o) => ({
              option: o,
              explanation: 'Does not satisfy the chemical principle or stoichiometric calculation.',
            })),
            solution: s.sol,
            conceptTested: s.topic,
            formulaUsed: s.f,
            estimatedTimeSeconds: timeSec,
            rotateIndex: idx,
          })
        );
      }
    });
  }
  return out;
}

